import numpy as np
import matplotlib.pyplot as plt
plt.rcParams['font.sans-serif'] = ['Microsoft YaHei', 'SimHei', 'DejaVu Sans']
plt.rcParams['axes.unicode_minus'] = False

DEG = np.pi / 180.0
XR = (-30.0 * DEG, 30.0 * DEG)
WR = (-120.0 * DEG, 120.0 * DEG)
UR = (-15.0, 15.0)


def trimf(x, a, b, c):
    """三角/肩形隶属度函数（标量）。a==b 为左肩，b==c 为右肩。"""
    if x <= a:
        return 1.0 if a == b else 0.0
    if x >= c:
        return 1.0 if b == c else 0.0
    return (x - a) / (b - a) if x <= b else (c - x) / (c - b)


def trimf_vec(x, a, b, c):
    """三角/肩形隶属度函数（向量化）。"""
    x = np.asarray(x, dtype=float)
    out = np.zeros_like(x)
    if b > a:
        m = (x > a) & (x <= b)
        out[m] = (x[m] - a) / (b - a)
    else:
        out[x <= b] = 1.0
    if c > b:
        m = (x > b) & (x < c)
        out[m] = (c - x[m]) / (c - b)
    else:
        out[x >= c] = 1.0
    return out


def trapmf_vec(x, a, b, c, d):
    x = np.asarray(x, dtype=float)
    out = np.zeros_like(x)
    m = (x > a) & (x <= b)
    if b > a:
        out[m] = (x[m] - a) / (b - a)
    else:
        out[x <= b] = 1.0
    out[(x > b) & (x <= c)] = 1.0
    m = (x > c) & (x < d)
    if d > c:
        out[m] = (d - x[m]) / (d - c)
    else:
        out[x >= c] = 1.0
    return out


def gaussmf_vec(x, c, s):
    return np.exp(-(np.asarray(x, dtype=float) - c) ** 2 / (2.0 * s * s))


def sigmf_vec(x, c, k):
    return 1.0 / (1.0 + np.exp(-k * (np.asarray(x, dtype=float) - c)))


def partition(lo, hi, n):
    """n 个语言值的均匀三角划分（首尾为肩形）。返回 [(a, b, c), ...]。"""
    ctr = np.linspace(lo, hi, n)
    return [(ctr[i - 1] if i > 0 else lo, ctr[i], ctr[i + 1] if i < n - 1 else hi)
            for i in range(n)]


def partition_hs(lo, hi, n, hs):
    """中心均匀分布、半宽 h = hs * s 的三角划分（首尾仍贴到论域边界）。"""
    ctr = np.linspace(lo, hi, n)
    s = ctr[1] - ctr[0]
    h = hs * s
    return [(ctr[i] - h if i > 0 else lo, ctr[i], ctr[i] + h if i < n - 1 else hi)
            for i in range(n)]

