def q_half_away(v, lim):
    """四舍五入（.5 远离零）后饱和到 [-lim, lim]；满足 q(-v) = -q(v)。"""
    s = np.sign(v)
    return int(s * min(lim, np.floor(abs(v) + 0.5)))


def famm(n, aw=1.0, bw=0.7):
    """中心反对称的模糊关联矩阵：out = q(-(aw*di + bw*dj)) + (n-1)/2。
    aw 是角速度的权重，bw 是角度的权重。"""
    c = (n - 1) / 2.0
    lim = int(c)
    return np.array([[q_half_away(-(aw * (i - c) + bw * (j - c)), lim) + int(c)
                      for j in range(n)] for i in range(n)], dtype=int)


class Mamdani2:
    """双输入单输出 Mamdani 控制器。输出隶属度函数预先算在网格上。"""

    def __init__(self, xr, wr, ur, n, M, and_op='min', impl='min',
                 defuzz='cog', ng=401, pad=0.0):
        self.PX = partition(*xr, n)
        self.PW = partition(*wr, n)
        self.PU = partition(*ur, n)
        self.M, self.n = M, n
        self.and_op, self.impl, self.defuzz = and_op, impl, defuzz
        self.ug = np.linspace(ur[0] - pad, ur[1] + pad, ng)
        self.mid = 0.5 * (ur[0] + ur[1])
        self.PU_grid = [trimf_vec(self.ug, *p) for p in self.PU]
        self.MX, self.MW = np.zeros(n), np.zeros(n)
        self.fired = 0

    def strengths(self, th, w):
        for i, p in enumerate(self.PX):
            self.MX[i] = trimf(th, *p)
        for j, p in enumerate(self.PW):
            self.MW[j] = trimf(w, *p)
        if self.and_op == 'min':
            return np.minimum(self.MX[:, None], self.MW[None, :])
        return self.MX[:, None] * self.MW[None, :]

    def aggregate(self, th, w):
        a = self.strengths(th, w)
        mu = np.zeros_like(self.ug)
        self.fired = 0
        for i in range(self.n):
            for j in range(self.n):
                ak = a[i, j]
                if ak <= 0.0:
                    continue
                self.fired += 1
                mz = self.PU_grid[self.M[i, j]]
                c = np.minimum(ak, mz) if self.impl == 'min' else ak * mz
                np.maximum(mu, c, out=mu)
        return mu

    def __call__(self, th, w):
        mu = self.aggregate(th, w)
        den = np.trapezoid(mu, self.ug)
        if den <= 1e-14:
            return self.mid
        if self.defuzz == 'cog':
            return float(np.trapezoid(self.ug * mu, self.ug) / den)
        if self.defuzz == 'mom':
            idx = np.where(mu >= mu.max() - 1e-12)[0]
            return float(np.mean(self.ug[idx]))
        cum = np.concatenate([[0.0], np.cumsum(0.5 * (mu[1:] + mu[:-1]) * np.diff(self.ug))])
        return float(np.interp(0.5 * cum[-1], cum, self.ug))


def pendulum_rhs(th, w, u, m=1.0, l=0.5, g=9.8, d0=0.0):
    ml2 = m * l * l
    return np.array([w, (m * g * l * np.sin(th) + u + d0) / ml2])


def simulate(ctrl, T=6.0, dt=1e-4, th0=20 * DEG, w0=0.0,
             m=1.0, l=0.5, g=9.8, umax=15.0, d0=0.0, ki=0.0):
    """RK4。控制量在四个 stage 内保持不变（本对象无显式时间依赖）。"""
    x = np.array([th0, w0])
    n = int(round(T / dt))
    hist = np.zeros((n + 1, 3))
    hist[0, :2] = x
    iz = 0.0
    for k in range(n):
        u = float(np.clip(ctrl(x[0], x[1]) - ki * iz, -umax, umax))
        hist[k + 1, 2] = u
        k1 = pendulum_rhs(x[0], x[1], u, m, l, g, d0)
        k2 = pendulum_rhs(x[0] + .5*dt*k1[0], x[1] + .5*dt*k1[1], u, m, l, g, d0)
        k3 = pendulum_rhs(x[0] + .5*dt*k2[0], x[1] + .5*dt*k2[1], u, m, l, g, d0)
        k4 = pendulum_rhs(x[0] + dt*k3[0], x[1] + dt*k3[1], u, m, l, g, d0)
        x = x + dt / 6 * (k1 + 2*k2 + 2*k3 + k4)
        iz += dt * x[0]
        hist[k + 1, :2] = x
        if not np.all(np.isfinite(x)) or abs(x[0]) > 1.5:
            return hist[:k + 2], (k + 1) * dt
    return hist, None


def perf(hist, esc, dt=1e-4, band=1.0):
    if esc is not None:
        return None
    th = hist[:, 0] / DEG
    u = hist[:, 2]
    inside = np.abs(th) <= band
    ts = 0.0
    for k in range(len(th) - 1, -1, -1):
        if not inside[k]:
            ts = k * dt
            break
    return dict(rms=float(np.sqrt(np.mean(th**2))), ss=float(abs(th[-1])),
                ts=float(ts), maxu=float(np.max(np.abs(u))),
                tv=float(np.sum(np.abs(np.diff(u)))), mx=float(np.max(np.abs(th))))


