import numpy as np
from scipy.integrate import quad

def mf(x, a, b, c):
    x = np.asarray(x, dtype=float)
    if a == b:
        return np.clip((c-x)/(c-b), 0, 1)
    if b == c:
        return np.clip((x-a)/(b-a), 0, 1)
    return np.maximum(0, np.minimum((x-a)/(b-a), (c-x)/(c-b)))

def audit(n=5, hs=1, x=5):
    cx=np.linspace(-30,30,n)
    cu=np.linspace(-15,15,n)
    h=hs*(cx[1]-cx[0])
    weights=np.array([float(mf(x, c-h if i else -30, c, c+h if i<n-1 else 30)) for i,c in enumerate(cx)])
    ug=np.linspace(-15,15,601)
    out=[]
    for i,w in enumerate(weights):
        j=n-1-i
        b=cu[j]
        a=cu[j-1] if j else -15
        c=cu[j+1] if j<n-1 else 15
        out.append(np.minimum(w,mf(ug,a,b,c)))
    mu=np.max(out,axis=0)
    area=np.trapezoid(mu,ug)
    if area<=1e-14:
        return {'valid':False,'fired':int(np.count_nonzero(weights)),'cog':0.,'bis':0.,'mom':0.}
    cum=np.r_[0,np.cumsum((mu[1:]+mu[:-1])/2*np.diff(ug))]
    return {'valid':True,'fired':int(np.count_nonzero(weights)), 'cog':float(np.trapezoid(ug*mu,ug)/area),
            'bis':float(np.interp(area/2,cum,ug)), 'mom':float(np.mean(ug[mu>=mu.max()-1e-12]))}

