def trimf_vec(x, a, b, c):
    x = np.asarray(x, dtype=float)
    out = np.zeros_like(x)
    if b > a:
        m = (x > a) & (x <= b)
        out[m] = (x[m] - a) / (b - a)
    else:
        out[x <= b] = 1.0
    if c > b:
        m = (x > b) & (x < c)
        out[m] = (c - x[m]) / (c - b)
    else:
        out[x >= c] = 1.0
    return out


def partition(lo, hi, n):
    ctr = np.linspace(lo, hi, n)
    return [(ctr[i - 1] if i > 0 else lo, ctr[i], ctr[i + 1] if i < n - 1 else hi)
            for i in range(n)]


def q_half_away(v, lim):
    s = np.sign(v)
    return int(s * min(lim, np.floor(abs(v) + 0.5)))


def famm(n, aw=1.0, bw=0.7):
    c = (n - 1) / 2.0
    lim = int(c)
    return np.array([[q_half_away(-(aw * (i - c) + bw * (j - c)), lim) + int(c)
                      for j in range(n)] for i in range(n)], dtype=int)


class Mamdani2:
    def __init__(self, xr, wr, ur, n, M, ng=401):
        self.PX, self.PW, self.PU = partition(*xr, n), partition(*wr, n), partition(*ur, n)
        self.M, self.n = M, n
        self.ug = np.linspace(ur[0], ur[1], ng)
        self.PU_grid = [trimf_vec(self.ug, *p) for p in self.PU]
        self.MX, self.MW = np.zeros(n), np.zeros(n)
        self.fired = 0

    def __call__(self, th, w):
        for i, p in enumerate(self.PX):
            self.MX[i] = trimf(th, *p)
        for j, p in enumerate(self.PW):
            self.MW[j] = trimf(w, *p)
        a = np.minimum(self.MX[:, None], self.MW[None, :])
        mu = np.zeros_like(self.ug)
        self.fired = 0
        for i in range(self.n):
            for j in range(self.n):
                ak = a[i, j]
                if ak <= 0.0:
                    continue
                self.fired += 1
                np.maximum(mu, np.minimum(ak, self.PU_grid[self.M[i, j]]), out=mu)
        den = np.trapezoid(mu, self.ug)
        if den <= 1e-14:
            return 0.0
        return float(np.trapezoid(self.ug * mu, self.ug) / den)


class Mamdani3:
    """三输入 Mamdani，同样跳过 alpha = 0 的规则。"""

    def __init__(self, n, ng=401):
        self.n = n
        self.P = [partition(*r, n) for r in (XR, WR, (-5.0, 5.0))]
        self.ug = np.linspace(-5.0, 5.0, ng)
        self.PUg = [trimf_vec(self.ug, *p) for p in self.P[2]]
        c = (n - 1) / 2.0
        self.M = np.array([[[q_half_away(-(1.0 * (i - c) + 0.7 * (j - c) + 0.5 * (k - c)), int(c)) + int(c)
                             for k in range(n)] for j in range(n)] for i in range(n)])
        self.fired = 0

    def __call__(self, x1, x2, x3):
        m = [np.array([trimf(v, *p) for p in self.P[t]]) for t, v in enumerate((x1, x2, x3))]
        agg = np.zeros_like(self.ug)
        self.fired = 0
        for i in range(self.n):
            if m[0][i] == 0:
                continue
            for j in range(self.n):
                a2 = min(m[0][i], m[1][j])
                if a2 == 0:
                    continue
                for k in range(self.n):
                    a = min(a2, m[2][k])
                    if a > 0:
                        self.fired += 1
                        np.maximum(agg, np.minimum(a, self.PUg[self.M[i, j, k]]), out=agg)
        d = np.trapezoid(agg, self.ug)
        return 0.0 if d <= 1e-14 else float(np.trapezoid(self.ug * agg, self.ug) / d)


def bench(f, N=2000):
    for _ in range(200):
        f()
    t0 = time.perf_counter()
    for _ in range(N):
        f()
    return (time.perf_counter() - t0) / N * 1e6


